import { tv, type VariantProps } from "@/lib/beton/tv";

export const newsletterSignup = tv({
  slots: {
    form: "flex w-full max-w-xl flex-col gap-3 sm:flex-row sm:items-start",
    field: "min-w-0 flex-1",
    note: "max-w-prose font-mono text-xs font-bold",
  },
});

export type NewsletterSignupVariants = VariantProps<typeof newsletterSignup>;

"use client";

import { newsletterSignup } from "@/lib/beton/recipes/newsletter-signup.recipe";
import { useId, type FormEvent, type ReactNode } from "react";
import { Button } from "@/components/ui/beton/button";
import { Field } from "@/components/ui/beton/field";
import { Input } from "@/components/ui/beton/input";
import { Section, type SectionProps } from "@/components/ui/beton/section";

export interface NewsletterSignupProps extends Omit<SectionProps, "children" | "onSubmit"> {
  /** What the address is for. */
  label?: ReactNode;
  /** Shown in the empty field. */
  placeholder?: string;
  /** The word on the button. */
  submitLabel?: ReactNode;
  /** The small print under the field. */
  note?: ReactNode;
  /** Where the form posts, for the case where JavaScript never arrives. */
  action?: string;
  /** Called with the address that was entered. */
  onSubscribe?: (email: string) => void;
}

/** One field and one button: the least you can ask for. */
export function NewsletterSignup({
  label = "Email address",
  placeholder = "you@example.com",
  submitLabel = "Subscribe",
  note,
  action,
  onSubscribe,
  ...props
}: NewsletterSignupProps) {
  const styles = newsletterSignup();
  const id = useId();

  function onSubmit(event: FormEvent<HTMLFormElement>) {
    if (!onSubscribe) return;
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubscribe(String(data.get("email") ?? ""));
  }

  return (
    <Section {...props}>
      <form action={action} method="post" onSubmit={onSubmit} className={styles.form()}>
        <Field className={styles.field()}>
          <Field.Label htmlFor={id}>{label}</Field.Label>
          <Input
            id={id}
            name="email"
            type="email"
            required
            autoComplete="email"
            placeholder={placeholder}
          />
          <Field.Error />
        </Field>
        <Button type="submit">{submitLabel}</Button>
      </form>
      {note ? <p className={styles.note()}>{note}</p> : null}
    </Section>
  );
}
